// Filter commits dalam 5 menit terakhir yang punya file .sql
const commits = $input.all();
const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);

const recentCommits = [];

for (const item of commits) {
  const commit = item.json;
  const commitDate = new Date(commit.commit?.author?.date || commit.created_at);

  if (commitDate > fiveMinutesAgo) {
    recentCommits.push({
      sha: commit.sha,
      message: commit.commit?.message || '',
      author: commit.commit?.author?.name || 'Unknown',
      date: commitDate.toISOString(),
      url: commit.html_url
    });
  }
}

if (recentCommits.length === 0) {
  return []; // Stop workflow jika tidak ada commit baru
}

return recentCommits.map(c => ({ json: c }));

// Extract .sql files dari commit
const commit = $input.first().json;
const files = commit.files || [];

const sqlFiles = files.filter(f => 
  f.filename.endsWith('.sql') && 
  (f.status === 'added' || f.status === 'modified')
);

if (sqlFiles.length === 0) {
  return []; // Tidak ada file SQL
}

return [{
  json: {
    sha: commit.sha,
    message: commit.commit?.message || '',
    author: commit.commit?.author?.name || 'Unknown',
    url: commit.html_url,
    sqlFiles: sqlFiles.map(f => ({
      filename: f.filename,
      raw_url: f.raw_url,
      status: f.status
    }))
  }
}];

// Parse CREATE TABLE statements dari SQL
const sqlContent = $input.first().json.data || $input.first().json.body || '';
const prevData = $('Extract SQL Files').first().json;

const tablePattern = /CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(?:public\.)?["']?(\w+)["']?\s*\(([\s\S]*?)\)(?:\s*;)?/gi;

const tables = [];
let match;

while ((match = tablePattern.exec(sqlContent)) !== null) {
  const tableName = match[1];
  const tableBody = match[2];

  const columns = [];
  const lines = tableBody.split(',');

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (/^(CONSTRAINT|PRIMARY\s+KEY\(|FOREIGN\s+KEY|UNIQUE\(|CHECK\(|INDEX)/i.test(trimmed)) continue;

    const colMatch = trimmed.match(/^["']?(\w+)["']?\s+(\w+(?:\([^)]+\))?)/i);
    if (colMatch) {
      columns.push({
        name: colMatch[1],
        type: colMatch[2]
      });
    }
  }

  if (columns.length > 0) {
    tables.push({
      name: tableName,
      columns: columns,
      definition: match[0]
    });
  }
}

return [{
  json: {
    ...prevData,
    tables,
    tableCount: tables.length,
    sqlContent
  }
}];

