// Format hasil untuk Telegram
const prevData = $('Parse PostgreSQL Tables').first().json;
const aiResponse = $input.first().json.message?.content || '{}';

// Parse AI response
let aiDoc = { tables: [] };
try {
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiDoc = JSON.parse(jsonMatch[0]);
  }
} catch (e) {}

// Build Telegram message
let msg = `🔔 *GITHUB SQL UPDATE*\n`;
msg += `━━━━━━━━━━━━━━━━━━━━━\n\n`;
msg += `📁 *File:* \`${prevData.sqlFiles[0].filename}\`\n`;
msg += `👤 *Author:* ${prevData.author}\n`;
msg += `💬 *Commit:* ${prevData.message.substring(0, 50)}\n`;
msg += `🔗 [View on GitHub](${prevData.url})\n\n`;
msg += `📚 *DOKUMENTASI PostgreSQL*\n`;
msg += `━━━━━━━━━━━━━━━━━━━━━\n\n`;

for (let i = 0; i < prevData.tables.length; i++) {
  const t = prevData.tables[i];
  const aiTable = aiDoc.tables?.find(at => at.name === t.name) || {};
  const desc = aiTable.description || `Tabel ${t.name}`;

  msg += `*${i + 1}. ${t.name}*\n`;
  msg += `📝 ${desc}\n\n\`\`\`\n`;

  for (let j = 0; j < t.columns.length; j++) {
    const c = t.columns[j];
    const colDesc = (aiTable.columns?.[c.name] || c.name).substring(0, 25);
    msg += `${j + 1}. ${c.name} (${c.type})\n   → ${colDesc}\n`;
  }

  msg += `\`\`\`\n\n`;
}

msg += `✅ *Total:* ${prevData.tableCount} table(s)`;

return [{ json: { message: msg, chatId: $vars.TELEGRAM_CHAT_ID } }];
